def transform(grid):
    h, w = len(grid), len(grid[0])
    coords = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    orientations = [
        (lambda r, c: r, lambda k: [(k, c) for c in range(w)] if 0 <= k < h else []),
        (lambda r, c: c, lambda k: [(r, k) for r in range(h)] if 0 <= k < w else []),
        (lambda r, c: r + c, lambda k: [(r, k-r) for r in range(h) if 0 <= k-r < w]),
        (lambda r, c: c - r, lambda k: [(r, r+k) for r in range(h) if 0 <= r+k < w]),
    ]
    choice = None
    for key_fn, cells_fn in orientations:
        groups = {}
        valid = True
        for r, c, color in coords:
            k = key_fn(r, c)
            if k in groups and groups[k][0] != color:
                valid = False
                break
            groups.setdefault(k, [color, set()])[1].add((r, c))
        if not valid or not groups:
            continue
        complete_cells = sum(len(pos) for k, (_, pos) in groups.items() if len(pos) == len(cells_fn(k)))
        complete_line_count = sum(len(pos) == len(cells_fn(k)) for k, (_, pos) in groups.items())
        completeness = sum(len(pos) / len(cells_fn(k)) for k, (_, pos) in groups.items())
        score = (complete_cells, complete_line_count, completeness)
        if choice is None or score > choice[0]:
            choice = (score, key_fn, cells_fn, groups)
    if choice is None:
        return [row[:] for row in grid]
    _, key_fn, cells_fn, groups = choice
    keys = list(groups)
    lo, hi = min(keys), max(keys)
    phases, period = None, None
    for p in range(1, hi - lo + 2):
        mapping = {}
        for k, (color, _) in groups.items():
            phase = k % p
            if phase in mapping and mapping[phase] != color:
                break
            mapping[phase] = color
        else:
            if len(mapping) == p:
                phases, period = mapping, p
                break
            if phases is None:
                phases, period = mapping, p
    if phases is None:
        return [row[:] for row in grid]
    # Fill unobserved phases by the closest preceding known phase in the cycle.
    for phase in range(period):
        if phase not in phases:
            prior = min(phases, key=lambda q: (phase - q) % period)
            phases[phase] = phases[prior]
    return [[phases[key_fn(r, c) % period] for c in range(w)] for r in range(h)]

